const C=document.querySelector('#game'),x=C.getContext('2d'),W=1280,H=720;
const $=s=>document.querySelector(s),ui={start:$('#start'),hud:$('#hud'),tools:$('#tools'),play:$('#play'),again:$('#again'),over:$('#over'),score:$('#score'),jump:$('#jump'),pause:$('#pause'),ink:$('#ink'),inkValue:$('#inkValue'),stage:$('#stage'),meters:$('#meters'),lives:$('#lives'),notice:$('#notice')};
const img={};for(const n of ['office','outdoors','workshop','robot-sheet','pencil','pickups-enemies-atlas']){img[n]=new Image();img[n].src=`assets/${n}.png`}const music=$('#bgm');music.volume=.25;function ensureMusic(){music.muted=false;music.volume=.25;if(!music.paused)return;let resumeAt=Number(music.dataset.resumeAt||0);if(resumeAt&&Math.abs(music.currentTime-resumeAt)>.15)music.currentTime=resumeAt;music.play().catch(()=>{})}music.addEventListener('timeupdate',()=>music.dataset.resumeAt=String(music.currentTime));addEventListener('pointerdown',ensureMusic,{once:true,passive:true});addEventListener('keydown',ensureMusic,{once:true});addEventListener('pagehide',()=>music.pause());addEventListener('beforeunload',()=>music.pause());
let state='menu',paused=false,cam=0,last=0,acc=0,frame=0,ink=100,lives=3,dist=0,score=0,slow=0,mouse=null,drawing=false,preview=[],strokes=[],plats=[],hazards=[],pickups=[],hurt=0;
let p={x:260,y:380,vx:150,vy:0,ground:false,coyote:0,jump:0,surface:null};C.width=W;C.height=H;
const theme=()=>{let d=dist%210;return d<70?'office':d<140?'outdoors':'workshop'};
function note(s){ui.notice.textContent=s;ui.notice.style.opacity=1;setTimeout(()=>ui.notice.style.opacity=0,1000)}
function reset(){ink=100;lives=3;score=0;dist=0;cam=0;strokes=[];p={x:260,y:380,vx:150,vy:0,ground:false,coyote:0,jump:0,surface:null};world()}
function world(){plats=[[-180,500,520,500]];hazards=[];pickups=[];for(let i=1;i<390;i++){let a=i*520,stage=Math.floor(a/7000)%3,pattern=i%5,base=stage===1?485:stage===2?505:520,lift=[0,80,145,55,190][pattern]+stage*25,y=base-lift,w=stage===0?330:stage===1?285:250;plats.push([a,y,a+w,y]);if(pattern===2)plats.push([a+w,y,a+w+150,y-65]);if(i>3&&pattern===1)hazards.push({x:a-54,y:base,w:48,stage});pickups.push({x:a+Math.min(120,w*.5),y:y-55,type:i%17===0?'heart':i%5===0?'ink':'star',taken:false})}}
function start(){state='playing';paused=false;ensureMusic();ui.start.hidden=ui.over.hidden=true;ui.hud.hidden=ui.jump.hidden=ui.pause.hidden=false;ui.tools.hidden=true;ui.tools.style.display='none';reset();last=performance.now();requestAnimationFrame(loop)}
function menu(){state='menu';paused=false;ui.over.hidden=true;ui.start.hidden=false;ui.hud.hidden=true;ui.jump.hidden=true;ui.pause.hidden=true;ui.tools.hidden=true;ui.tools.style.display='none'}
function jump(){if(state==='playing'&&!paused)p.jump=.12}ui.play.onclick=start;ui.again.onclick=menu;ui.jump.onclick=jump;ui.jump.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();jump()},{passive:false});ui.pause.onclick=()=>toggle();
function toggle(){if(state!=='playing')return;paused=!paused;note(paused?'PAUSED':'GO!');if(!paused){last=performance.now();requestAnimationFrame(loop)}}
addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();p.jump=.12}if(e.key==='p'||e.key==='Escape')toggle();if(e.key==='r'&&state==='over')start();if('123'.includes(e.key)&&state==='playing'){p.x=(+e.key-1)*7000+340;p.y=280;p.vx=180;cam=p.x-260;note('TEST WARP')}});
function point(e){let r=C.getBoundingClientRect(),sx=(e.clientX-r.left)*W/r.width,sy=(e.clientY-r.top)*H/r.height;return{screen:{x:sx,y:sy},world:{x:sx+cam,y:sy}}}
function add(q){let z=preview.at(-1);if(!z||Math.hypot(q.x-z.x,q.y-z.y)>3)preview.push(q)}
let activePointer=null;function beginStroke(e){if(state!=='playing'||paused||activePointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();let q=point(e);activePointer=e.pointerId;mouse=q.screen;drawing=true;preview=[q.world];slow=2;C.setPointerCapture?.(e.pointerId)}function moveStroke(e){let samples=e.getCoalescedEvents?.()||[e];if(e.pointerType==='mouse'){for(const m of samples)mouse=point(m).screen}if(e.pointerId!==activePointer)return;e.preventDefault();for(const m of samples){let q=point(m);mouse=q.screen;if(drawing)add(q.world)}}function endStroke(e){if(e.pointerId!==activePointer)return;commit();activePointer=null}C.addEventListener('pointerdown',beginStroke,{passive:false});C.addEventListener('pointermove',moveStroke,{passive:false});C.addEventListener('pointerup',endStroke);C.addEventListener('pointercancel',endStroke);C.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')mouse=null});C.addEventListener('contextmenu',e=>e.preventDefault());
function commit(){if(!drawing)return;drawing=false;if(preview.length>1){let len=preview.reduce((n,q,i)=>i?n+Math.hypot(q.x-preview[i-1].x,q.y-preview[i-1].y):0,0),max=Math.min(1000,ink*10);if(len>max){let out=[preview[0]],used=0;for(let i=1;i<preview.length;i++){let a=out.at(-1),b=preview[i],d=Math.hypot(b.x-a.x,b.y-a.y);if(used+d>max)break;out.push(b);used+=d}preview=out;len=used}if(preview.length>1){if(strokes.length===3)strokes.shift();strokes.push({pts:preview,life:7});ink=Math.max(0,ink-len/10)}}preview=[]}
function segments(){let a=plats.map(q=>({a:{x:q[0],y:q[1]},b:{x:q[2],y:q[3]},drawn:false}));for(const s of strokes)for(let i=1;i<s.pts.length;i++)a.push({a:s.pts[i-1],b:s.pts[i],drawn:true});return a}
function at(px,oldY,newY){let best;for(const s of segments()){if(px<Math.min(s.a.x,s.b.x)||px>Math.max(s.a.x,s.b.x))continue;let t=(px-s.a.x)/(s.b.x-s.a.x),y=s.a.y+(s.b.y-s.a.y)*t;if(oldY<=y+2&&newY>=y-2&&(!best||y<best.y))best={y,s}}return best}
function tick(dt){slow=Math.max(0,slow-dt);hurt=Math.max(0,hurt-dt);let stage=theme(),base=stage==='office'?300:stage==='outdoors'?350:400,old=p.y,down=p.surface?(p.surface.b.y-p.surface.a.y)/(p.surface.b.x-p.surface.a.x):0,target=(base+Math.min(220,dist*.55)+(p.surface?.drawn?120+Math.max(0,down)*400:0))*(slow?.42:1);p.vx+=(target-p.vx)*Math.min(1,4*dt);if(p.surface?.drawn&&down>0)p.vx+=down*1600*dt;p.vx=Math.min(760,Math.max(150,p.vx));p.x+=p.vx*dt;dist=p.x/100;p.vy+=1500*dt;p.y+=p.vy*dt;p.jump-=dt;let l=at(p.x+8,old+62,p.y+62),r=at(p.x+40,old+62,p.y+62),h=[l,r].filter(Boolean).sort((a,b)=>a.y-b.y)[0];p.ground=false;if(h&&p.vy>=0){p.y=h.y-62;p.vy=0;p.ground=true;p.coyote=.1;p.surface=h.s}else{p.surface=null;p.coyote-=dt}if(p.jump>0&&(p.ground||p.coyote>0)){p.vy=-560;p.jump=0;p.ground=false}for(const h of hazards)if(hurt<=0&&p.x+40>h.x&&p.x<h.x+h.w&&p.y+62>h.y-10)damage();for(const q of pickups)if(!q.taken&&Math.hypot(p.x-q.x,p.y-q.y)<58){q.taken=true;if(q.type==='ink')ink=Math.min(100,ink+25);else if(q.type==='heart')lives=Math.min(3,lives+1);else score+=25}if(p.y>800&&hurt<=0)damage();strokes.forEach(s=>s.life-=dt);strokes=strokes.filter(s=>s.life>0||p.x<Math.max(...s.pts.map(q=>q.x))+55);if(!drawing)ink=Math.min(100,ink+8*dt);cam=Math.max(0,p.x-260)}
function damage(){hurt=1;lives--;p.x=Math.max(260,Math.floor(p.x/520)*520+45);p.y=270;p.vx=170;p.vy=0;ink=100;note('OOPS!');if(lives<=0){state='over';ui.over.hidden=false;ui.score.textContent=`${Math.floor(dist)} m · ${score} points`;ui.hud.hidden=true;ui.jump.hidden=true;ui.pause.hidden=true;setTimeout(()=>{if(state==='over')menu()},1600)}}
function line(a,b,c,w){x.strokeStyle=c;x.lineWidth=w;x.lineCap='round';x.lineJoin='round';x.beginPath();x.moveTo(a.x-cam,a.y);x.lineTo(b.x-cam,b.y);x.stroke()}function path(pts,c,w){if(pts.length<2)return;x.strokeStyle=c;x.lineWidth=w;x.lineCap='round';x.lineJoin='round';x.beginPath();x.moveTo(pts[0].x-cam,pts[0].y);for(let i=1;i<pts.length;i++)x.lineTo(pts[i].x-cam,pts[i].y);x.stroke()}
function draw(){let n=theme();x.drawImage(img[n],0,0,W,H);if(n==='outdoors'){x.fillStyle='#b9e5f5';x.fillRect(0,372,W,H-372);x.fillStyle='#e9fbff';x.beginPath();x.moveTo(0,446);for(let i=0;i<=W;i+=64)x.quadraticCurveTo(i+32,424+(i/64%2)*10,i+64,444);x.lineTo(W,720);x.lineTo(0,720);x.fill()}x.fillStyle='rgba(28,0,74,.1)';x.fillRect(0,0,W,H);for(const a of plats){let top=n==='outdoors'?'#eef8ff':'#fff1ce',edge=n==='office'?'#6400e8':n==='outdoors'?'#6876bb':'#f400a1';line({x:a[0],y:a[1]},{x:a[2],y:a[3]},'#4d2376',34);line({x:a[0],y:a[1]},{x:a[2],y:a[3]},top,23);line({x:a[0],y:a[1]},{x:a[2],y:a[3]},edge,5)}for(const h of hazards){let sx=h.stage===2?362:h.stage===1?1086:362,sy=h.stage===2?724:362,cx=h.x-cam+18,cy=h.y-29;x.save();x.translate(cx,cy);if(h.stage===2)x.rotate(frame*.14);x.drawImage(img['pickups-enemies-atlas'],sx,sy,362,362,-31,-31,62,62);x.restore()}for(const q of pickups){if(q.taken)continue;let sx=q.type==='ink'?1086:q.type==='heart'?362:0,sy=q.type==='heart'?0:0,size=q.type==='ink'?52:q.type==='heart'?40:48;if(q.type==='star'){x.save();x.globalAlpha=.32+.14*Math.sin(frame*.12);x.fillStyle='#ffd229';x.beginPath();x.arc(q.x-cam,q.y-18,30,0,Math.PI*2);x.fill();x.restore()}x.drawImage(img['pickups-enemies-atlas'],sx,sy,362,362,q.x-cam-size/2,q.y-size+4,size,size)}for(const s of strokes){path(s.pts,'#6400e8',18);path(s.pts,'#fff1ce',7)}if(preview.length>1)path(preview,'#f400a1',9);let fi=p.vy<0?5:p.vy>160?6:p.ground?Math.floor(frame/8)%4:4,fw=1774/4,fh=887/2;x.drawImage(img['robot-sheet'],(fi%4)*fw,Math.floor(fi/4)*fh,fw,fh,p.x-cam-24,p.y-34,96,96);if(mouse)x.drawImage(img.pencil,mouse.x-7,mouse.y-65,68,68)}
function loop(t){if(state!=='playing'||paused)return;let d=Math.min(.04,(t-last)/1000);last=t;acc+=d;while(acc>=1/120){tick(1/120);acc-=1/120}frame++;draw();ui.ink.style.width=ink+'%';ui.inkValue.textContent=Math.ceil(ink)+'/100';ui.stage.textContent=theme()==='office'?'CREATIVE OFFICE':theme()==='outdoors'?'WINTER OUTDOORS':'HOLIDAY WORKSHOP';ui.meters.textContent=`${Math.floor(dist)} m · ${score} pts`;ui.lives.style.visibility='visible';ui.lives.textContent='♥ '.repeat(lives);requestAnimationFrame(loop)}
